// Generado desde public/brand/carta-viva/isotipo.png (77214 bytes).
// Se mantiene inline en el bundle para que el PDF funcione en runtime
// serverless (Vercel), donde public/ no está disponible en el fs de la
// lambda. Regenerar con: node scripts/generate-isotipo-base64.mjs
// (si cambiara el PNG; hoy se ha generado a mano desde la rama feat/pdf-marca).

export const ISOTIPO_PNG_WIDTH  = 512
export const ISOTIPO_PNG_HEIGHT = 512

// base64 del PNG completo (77 KB → ~103 KB base64). jsPDF acepta el
// data URL completo o el buffer binario; exponemos ambas utilidades.
export const ISOTIPO_PNG_BASE64 = ''

/** Devuelve el buffer binario (Uint8Array) del isotipo. */
export function getIsotipoBuffer() {
  // Node 18+ y navegadores modernos soportan atob/Buffer.
  if (typeof Buffer !== 'undefined') {
    return Buffer.from(ISOTIPO_PNG_BASE64, 'base64')
  }
  const binary = atob(ISOTIPO_PNG_BASE64)
  const out = new Uint8Array(binary.length)
  for (let i = 0; i < binary.length; i++) out[i] = binary.charCodeAt(i)
  return out
}
